let ctx=null,active=null,markMode=false,selection=null,press=null,tap=null,clickTimer=null,dictPromise=null,dict=null,articleAids={},cleanups=[],generation=0,cardGeneration=0,storageWarning=false,pendingReturn=null,consumed=null,gesture=null,modalReturn=null;
