function decorate(text,start,anns){const end=start+text.length,bounds=[start,end];for(const a of anns){if(a.start<end&&a.end>start)bounds.push(Math.max(start,a.start),Math.min(end,a.end))}const sorted=[...new Set(bounds)].sort((a,b)=>a-b);let html='';for(let i=0;i<sorted.length-1;i++){const x=sorted[i],y=sorted[i+1],a=anns.find(a=>a.start<=x&&a.end>=y);const bit=E(text.slice(x-start,y-start));html+=a?`<mark class="rt-mark rt-${a.color}" data-mark="${E(a.id)}" title="${E(a.note||'点击编辑批注')}">${bit}</mark>`:bit}return html}
