function hidePalette(){const x=$('.rt-selectionbar');if(x)x.hidden=true}
function showPalette(){let bar=$('.rt-selectionbar');if(!bar){bar=document.createElement('div');bar.className='rt-selectionbar';bar.setAttribute('role','toolbar');bar.setAttribute('aria-label','选中文字的批注工具');document.body.appendChild(bar)}bar.hidden=false;bar.onpointerdown=e=>{if(e.button===0)e.preventDefault()};if(bar.dataset.built)return;bar.dataset.built='true';bar.innerHTML=Object.entries(colors).map(([c,n])=>`<button class="rt-color rt-${c}" data-color="${c}" aria-label="${n}" title="${n}"></button>`).join('')+'<button id="rt-keep-selection">收入词本</button><button id="rt-note-selection" class="ui-icon-button" aria-label="写批注" title="写批注"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m15 4 5 5M4 20l5-1L20 8a2 2 0 0 0-5-5L4 14z"/></svg></button><button id="rt-cancel-selection" class="ui-icon-button" aria-label="取消选择" title="取消选择"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m6 6 12 12M18 6 6 18"/></svg></button>';bar.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>addAnnotation(b.dataset.color,''));$('#rt-note-selection').onclick=noteEditor;$('#rt-keep-selection').onclick=keepSelection;$('#rt-cancel-selection').onclick=()=>{window.getSelection()?.removeAllRanges();hidePalette();selection=null}}
function keepSelection(){if(!active||!selection)return;const sel={...selection},article=active;const word=sel.quote.trim().replace(/\s+/g,' ');if(word.length>120||word.split(/\s+/).length>12){notify('请选一个单词或较短的短语（最多 12 个词）');return}openCard('收入词本',`<h2 class="vocab-word" lang="en">${E(word)}</h2><p class="small">短语暂不自动翻译，可以记下你的理解，也可以先留空。</p><label for="rt-phrase-meaning">释义或提示（选填）</label><textarea id="rt-phrase-meaning" maxlength="1000" placeholder="例如：在……方面"></textarea><button class="primary" id="rt-phrase-save">收入词本</button>`);$('#rt-phrase-save').onclick=()=>{const meaning=$('#rt-phrase-meaning').value.trim()||'待补充释义';saveEntry({word,meaning,kind:word.split(/\s+/).length>1?'phrase':'word',source:'own',context:{articleId:article.id,title:article.title,quote:fallbackSentence(sel.p,sel.start,sel.end).text,paragraphIndex:sel.p}},()=>{$('#note').close();hidePalette();window.getSelection()?.removeAllRanges()})}}
