function annotationList(){const list=db.annotations.filter(a=>a.articleId===active.id);openCard('本篇批注',list.length?list.map(a=>`<button class="rt-note-item" data-edit-note="${E(a.id)}"><span class="rt-swatch rt-${colors[a.color]?a.color:'yellow'}"></span><span><span lang="en">${E(a.quote)}</span>${a.note?`<small>${E(a.note)}</small>`:''}${active.paragraphs[a.paragraphIndex]?.slice(a.start,a.end)!==a.quote?'<small>原文已变化，位置需要重新确认</small>':''}</span></button>`).join('')+'<button class="ui-icon-button quiet" id="rt-export-notes" aria-label="'+exportLabel()+'" title="'+exportLabel()+'"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/></svg></button>':'<p class="empty">还没有批注。点“划线 / 批注”，再选中一段文字。</p>');document.querySelectorAll('[data-edit-note]').forEach(b=>b.onclick=()=>noteEditor(b.dataset.editNote));if($('#rt-export-notes'))$('#rt-export-notes').onclick=exportFile}
function toolbarMenu(){openCard('阅读工具','<div class="preference-list"><button id="rt-all-notes"><span>全部笔记</span><strong>阅读与词汇 ›</strong></button><button id="rt-mark-toggle"><span>选择文字 / 批注</span><strong>彩色记号笔 ›</strong></button><button id="rt-notes"><span>本篇批注</span><strong>'+db.annotations.filter(x=>x.articleId===active.id).length+' 条 ›</strong></button><button id="rt-access"><span>查词 / 整句</span><strong>键盘与辅助操作 ›</strong></button><button id="rt-help"><span>使用说明</span><strong>›</strong></button></div>');$('#rt-all-notes').onclick=()=>{$('#note').close();location.hash='notes'};$('#rt-mark-toggle').onclick=()=>{$('#note').close();setMarkMode(!markMode)};$('#rt-notes').onclick=annotationList;$('#rt-help').onclick=()=>tutorial(true);$('#rt-access').onclick=accessLookup}
function accessLookup(){openCard('查词 / 整句','<label for="rt-access-word">输入本篇中的一个英文单词</label><input id="rt-access-word" class="search" lang="en" autocomplete="off"><div class="rt-actions"><button class="pill" id="rt-access-meaning">看词义</button><button class="pill" id="rt-access-sentence">看整句</button></div><div id="rt-occurrences"></div><p class="small">出现多次时，可以选择具体的那一句。</p>');const run=action=>{$('#rt-occurrences').innerHTML='';$('#rt-dialog-status').textContent='';const word=$('#rt-access-word').value.trim();if(!word){cardStatus('先输入一个词',$('#rt-access-word'));return}const matches=[];const escaped=word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');for(let p=0;p<active.paragraphs.length;p++){const re=new RegExp('\\b'+escaped+'\\b','gi');for(const m of active.paragraphs[p].matchAll(re))matches.push({word:m[0],p,start:m.index,end:m.index+m[0].length})}if(!matches.length){cardStatus('本篇没有找到这个词',$('#rt-access-word'));return}const show=info=>action==='sentence'?showSentence(info):showWord(info);if(matches.length===1){show(matches[0]);return}$('#rt-occurrences').innerHTML='<p class="small">共 '+matches.length+' 处，选择你要看的位置：</p>'+matches.map((m,i)=>`<button class="rt-occurrence" data-occurrence="${i}"><small>第 ${m.p+1} 段 · 第 ${i+1} 处</small><span lang="en">${E(fallbackSentence(m.p,m.start,m.end).text)}</span></button>`).join('');$('#rt-occurrences').querySelectorAll('button').forEach(b=>b.onclick=()=>show(matches[+b.dataset.occurrence]));$('#rt-occurrences button')?.focus()};$('#rt-access-meaning').onclick=()=>run('word');$('#rt-access-sentence').onclick=()=>run('sentence');$('#rt-access-word').onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();run('word')}};$('#rt-access-word').focus()}
let guideSeenInMemory=false;
function tutorial(force){let seen=guideSeenInMemory;try{seen=seen||localStorage.getItem('naodai-reader-guide-v2')==='done'}catch{}try{seen=seen||sessionStorage.getItem('naodai-reader-guide-v2')==='done'}catch{}if(seen&&!force)return;guideSeenInMemory=true;try{localStorage.setItem('naodai-reader-guide-v2','done')}catch{}try{sessionStorage.setItem('naodai-reader-guide-v2','done')}catch{}openCard('读的时候，可以这样用','<div class="rt-guide"><div><span>01</span><p><strong>长按单词，查看词义</strong><small>部分专名或新词暂未收录，也可以自己补充。</small></p></div><div><span>02</span><p><strong>双击 / 双点单词，查看整句解析</strong><small>已有讲解直接显示；其余提供标明限制的自动句法线索。</small></p></div><div><span>03</span><p><strong>点独立的“译文”按钮，看中文</strong><small>文章开头点“译文”，再点段落下的“本段译文”，或“展开全文译文”。中文译文来自本站预先整理的内容，不会临时调用 AI；收起后继续只读英文。译文按钮与原文分开，不占用长按查词或双点整句解析。</small></p></div><div><span>04</span><p><strong>用记号笔，留下想法</strong><small>点右下角的笔，进入“选择文字 / 批注”；此时使用系统文字选择，可在英文原文中做批注或把短语收入词本，也可轻点已有标记编辑。</small></p></div></div><p class="small">留下的词语会进入“我的词本”，随时回顾。支持双指缩放。文字选择模式使用系统操作，也可用工具里的输入框查词。</p><div class="rt-actions"><button class="primary" id="rt-guide-done">开始读</button><button class="quiet" id="rt-guide-later">稍后再看</button></div>');const dismiss=()=>{guideSeenInMemory=true;try{localStorage.setItem('naodai-reader-guide-v2','done')}catch{}try{sessionStorage.setItem('naodai-reader-guide-v2','done')}catch{}$('#note').close()};$('#rt-guide-done').onclick=dismiss;$('#rt-guide-later').onclick=dismiss}
function attach(r,options){cleanup();active=r;ctx=options;window.ReadingHints?.attach?.(r);const area=$('.reading');if(!area)return;area.innerHTML=renderPassage(r);/* static-translations-v1 */window.ReadingTranslation?.mount(r,area);area.setAttribute('aria-label','英文原文；长按查词，双击看整句');const floating=document.createElement('button');floating.className='rt-floating';floating.setAttribute('aria-label','阅读工具：划线批注、查词和帮助');floating.title='阅读工具：划线批注、查词和帮助';floating.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 16 11-11 3 3L8 19H5v-3Zm9-9 3 3M4 22h16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';floating.onclick=toolbarMenu;document.body.appendChild(floating);
const scope=generation;const token=e=>{const element=e.target?.closest?.('.rt-token');return element&&area.contains(element)?element:null};const infoFor=el=>el?tokenInfo(el):null;const keyFor=el=>el?r.id+'|'+scope+'|'+el.dataset.token:null;
const eventData=(e,el=token(e))=>({id:e.pointerId??'mouse',type:e.pointerType||'mouse',key:keyFor(el),info:infoFor(el),x:e.clientX??0,y:e.clientY??0,button:e.button??0,isPrimary:e.isPrimary!==false,modifiers:!!(e.altKey||e.ctrlKey||e.metaKey||e.shiftKey)});
gesture=new ReaderGestureEngine.Controller({enabled:()=>active?.id===r.id&&generation===scope&&!markMode&&!$('#note').open&&document.visibilityState!=='hidden',onWord:showWord,onSentence:showSentence,onCancel:cancelClicks});
if('PointerEvent'in window){listen(document,'pointerdown',e=>gesture?.pointerDown(eventData(e)),{capture:true,passive:true});listen(document,'pointermove',e=>gesture?.pointerMove(eventData(e)),{capture:true,passive:true});listen(document,'pointerup',e=>gesture?.pointerUp(eventData(e)),{capture:true,passive:true});listen(document,'pointercancel',e=>gesture?.pointerCancel(eventData(e)),{capture:true,passive:true});listen(document,'lostpointercapture',e=>gesture?.lostCapture(eventData(e)),{capture:true,passive:true})}
else{let ignoreMouseUntil=0;const eachTouch=(e,method)=>{ignoreMouseUntil=Date.now()+1500;for(const t of e.changedTouches||[]){const el=t.target?.closest?.('.rt-token');const inside=el&&area.contains(el)?el:null;gesture?.[method]({id:'touch-'+t.identifier,type:'touch',key:keyFor(inside),info:infoFor(inside),x:t.clientX,y:t.clientY,button:0,isPrimary:true,modifiers:false})}};listen(document,'touchstart',e=>eachTouch(e,'pointerDown'),{capture:true,passive:true});listen(document,'touchmove',e=>eachTouch(e,'pointerMove'),{capture:true,passive:true});listen(document,'touchend',e=>eachTouch(e,'pointerUp'),{capture:true,passive:true});listen(document,'touchcancel',e=>eachTouch(e,'pointerCancel'),{capture:true,passive:true});for(const [event,method]of[['mousedown','pointerDown'],['mousemove','pointerMove'],['mouseup','pointerUp']])listen(document,event,e=>{if(Date.now()>=ignoreMouseUntil)gesture?.[method](eventData(e))},{capture:true,passive:true})}
listen(area,'pointerleave',()=>{if(gesture?.press?.type==='mouse')gesture.cancel('leave-reader')});listen(document,'scroll',()=>gesture?.cancel('scroll'),{capture:true,passive:true});listen(window,'scroll',()=>gesture?.cancel('scroll'),{passive:true});listen(window,'wheel',()=>gesture?.cancel('wheel'),{passive:true});listen(window,'blur',()=>gesture?.reset('window-blur'));listen(window,'pagehide',()=>gesture?.reset('page-hide'));listen(window,'orientationchange',()=>gesture?.reset('orientation-change'));listen(document,'visibilitychange',()=>{if(document.visibilityState==='hidden')gesture?.reset('document-hidden')});listen(document,'keydown',()=>gesture?.cancel('keyboard',{resetPointers:true}));
listen(area,'contextmenu',e=>{if(markMode)return;const el=token(e);if(el&&gesture?.contextMenu(keyFor(el),{pointerType:e.pointerType||''}))e.preventDefault()});
listen(area,'click',e=>{const el=token(e);if(!markMode&&el&&gesture?.shouldSuppressClick(keyFor(el))){e.preventDefault();return}if(markMode){const mark=e.target.closest('[data-mark]');if(mark&&!window.getSelection()?.toString())noteEditor(mark.dataset.mark)}});
listen(area,'dblclick',e=>{if(markMode)return;const el=token(e);if(el&&gesture?.doubleClick(keyFor(el),infoFor(el),{modifiers:!!(e.altKey||e.ctrlKey||e.metaKey||e.shiftKey)}))e.preventDefault()});
listen(document,'selectionchange',()=>{if(markMode)captureSelection()});listen(document,'pointerup',()=>{if(markMode)setTimeout(captureSelection,0)});listen(document,'keyup',e=>{if(markMode&&e.key.startsWith('Arrow'))captureSelection()});
if(pendingReturn?.articleId===r.id){const origin={...pendingReturn},ticket=generation;pendingReturn=null;const para=area.querySelector('[data-paragraph="'+Number(origin.paragraphIndex)+'"]');para?.classList.add('rt-return-context');requestAnimationFrame(()=>{if(ticket===generation&&area.isConnected)para?.scrollIntoView?.({block:'center'})})}reviewReturnControl(area,r);refreshArticleReview();tutorial(false)}
// A quiet, article-scoped entry appears only after this article is complete.
function refreshArticleReview(){
 const finish=$('.finish');let section=$('#rt-article-review');
 if(!active||!ctx?.completed||!finish){section?.remove();return}
 const id=active.id,words=db.words.filter(w=>w.contexts.some(c=>c.articleId===id)),notes=db.annotations.filter(a=>a.articleId===id);
 if(!words.length&&!notes.length){section?.remove();return}
 if(!section){section=document.createElement('section');section.id='rt-article-review';section.className='rt-article-review';section.setAttribute('aria-label','本篇回顾');section.innerHTML='<p class="small">本篇回顾</p>';finish.after(section)}
 const entry=(key,count,label,action)=>{let button=section.querySelector('#'+key);if(!count){button?.remove();return}if(!button){button=document.createElement('button');button.id=key;button.className='quiet';section.appendChild(button)}button.textContent=label+' · '+count+' 条 →';button.onclick=()=>{if(active?.id===id&&ctx?.completed&&button.isConnected)action()}};
 entry('rt-finish-words',words.length,'词语与短语',()=>openVocabulary(id));
 entry('rt-finish-notes',notes.length,'高亮与批注',annotationList);
}
function afterFinish(id,completed=true){if(active?.id!==id)return;ctx.completed=completed;refreshArticleReview()}
function exportData(){return {version:1,storage:storageLabel(),annotations:db.annotations,words:db.words,review:R.exportData(),exportedAt:new Date().toISOString()}}
function exportFile(){if(window.LearningBackup){try{window.LearningBackup.download()}catch(e){notify(e.message)}return;}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(exportData(),null,2)],{type:'application/json;charset=utf-8'}));a.href=url;a.download='脑袋加一-批注与单词.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let wordQuery='',wordKind='all',reviewDeck=[],reviewIndex=0,vocabularyArticle=null,reviewRound=null,reviewResume=['#words','#wordbook'].includes(location.hash),reviewOrigin=null;
const WORD_VIEW='naodai-wordbook-view-v1';
if(['#words','#wordbook'].includes(location.hash)){try{const saved=JSON.parse(sessionStorage.getItem(WORD_VIEW));if(saved?.version===1){wordQuery=typeof saved.query==='string'?saved.query.slice(0,1000):'';wordKind=['all','word','phrase'].includes(saved.kind)?saved.kind:'all';vocabularyArticle=typeof saved.article==='string'&&saved.article.length<=200?saved.article:null}}catch{}}
