function bindWordRows(){document.querySelectorAll('[data-vocab-id]').forEach(b=>b.onclick=()=>savedWord(db.words.find(w=>w.id===b.dataset.vocabId)))}
function renderVocabulary(container,options){cleanup();ctx=options;R.migrate(db.words);if(reviewResume){reviewResume=false;const saved=R.loadRound('wordbook',db.words);if(saved){reviewRound=saved;review(container);return}}document.body.classList.remove('is-reading','is-onboarding');const scope=db.words.filter(w=>(!vocabularyArticle||w.contexts.some(c=>c.articleId===vocabularyArticle))&&(wordKind==='all'||(w.kind||'word')===wordKind));const list=scope.filter(w=>(w.word+' '+w.meaning).toLowerCase().includes(wordQuery.trim().toLowerCase()));container.innerHTML=`<section class="library rt-vocabulary"><button class="ui-icon-button back" id="rt-vocab-back" aria-label="返回英语" title="返回英语"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m14 6-6 6 6 6"/><path d="M8 12h12"/></svg></button><div class="rt-vocab-heading"><h1>我的词本</h1><button class="ui-icon-label quiet" id="rt-book-notes" aria-label="全部笔记" title="全部笔记"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 3h14v18H6a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2M8 3v18M11 8h6M11 12h6M11 16h4"/></svg><span>笔记</span></button><span class="small">${scope.length} 条${vocabularyArticle?' · 来自本篇':''}</span></div>${vocabularyArticle?'<button class="quiet" id="rt-all-words">查看全部单词 →</button>':''}<div class="track-tabs" aria-label="词本类型">${[['all','全部'],['word','单词'],['phrase','短语']].map(([k,v])=>`<button class="pill" data-word-kind="${k}" aria-pressed="${wordKind===k}">${v}</button>`).join('')}</div>${db.words.length?`<button class="primary" id="rt-review-start" ${R.available(list).length||R.loadRound('wordbook',list)?'':'disabled'}>开始回顾 →</button>${!R.available(list).length?'<p class="small">暂时没有到期的词，可以随时浏览。</p>':''}${R.due(list)?`<p class="small">${R.due(list)} 条到期可回顾</p>`:''}<label class="search-label" for="rt-word-search">搜索词本</label><input class="search" id="rt-word-search" placeholder="单词或释义" value="${E(wordQuery)}"><div id="rt-word-results">${wordRows(list)}</div><details><summary>数据与备份</summary><p>${storageLabel()}，不跨设备同步。清理浏览器数据可能丢失本机记录。</p><button class="ui-icon-button quiet" id="rt-vocab-export" aria-label="${exportLabel()}" title="${exportLabel()}"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/></svg></button></details>`:'<p class="empty">读文章或背词时点“收入词本”，喜欢的单词和短语就会留在这里。</p><button class="primary" id="rt-vocab-read">去学词汇 →</button>'}</section>`;window.AppNav?.bind($('#rt-vocab-back'),'english');$('#rt-book-notes').onclick=()=>location.hash='notes';document.querySelectorAll('[data-word-kind]').forEach(b=>b.onclick=()=>{if(!b.isConnected||wordKind===b.dataset.wordKind)return;const moveFocus=b.contains(document.activeElement);wordKind=b.dataset.wordKind;renderVocabulary(container,options);if(moveFocus&&!$('#note').open)container.querySelector('[data-word-kind="'+wordKind+'"]')?.focus({preventScroll:true})});if($('#rt-vocab-read'))$('#rt-vocab-read').onclick=()=>location.hash='vocabulary';if($('#rt-review-start'))$('#rt-review-start').onclick=()=>{askStorage(()=>{const pool=scope.filter(w=>(w.word+' '+w.meaning).toLowerCase().includes(wordQuery.trim().toLowerCase()));reviewRound=R.loadRound('wordbook',pool)||R.createRound(pool,12);review(container)})};const allWordsButton=$('#rt-all-words');if(allWordsButton)allWordsButton.onclick=()=>{if(!allWordsButton.isConnected)return;const moveFocus=allWordsButton.contains(document.activeElement);vocabularyArticle=null;wordQuery='';renderVocabulary(container,options);focusReplacement(container.querySelector('h1'),moveFocus)};if($('#rt-word-search')){const input=$('#rt-word-search');const filter=()=>{wordQuery=input.value;const matches=scope.filter(w=>(w.word+' '+w.meaning).toLowerCase().includes(wordQuery.trim().toLowerCase()));$('#rt-word-results').innerHTML=wordRows(matches);$('#rt-review-start').disabled=!R.available(matches).length&&!R.loadRound('wordbook',matches);bindWordRows()};input.oninput=e=>{if(!e.isComposing)filter()};input.oncompositionend=filter}bindWordRows();if($('#rt-vocab-export'))$('#rt-vocab-export').onclick=exportFile}
function savedWord(w){openCard('词本 · 随时回看',`<h2 class="vocab-word" lang="en">${E(w.word)}</h2><p class="vocab-meaning rt-definition">${E(w.meaning)}</p>${w.contexts.map((c,i)=>({c,i})).filter(({c})=>!vocabularyArticle||c.articleId===vocabularyArticle).map(({c,i})=>`<p class="vocab-context" lang="en">${E(c.quote)}</p>${c.exampleZh?`<p class="small">${E(c.exampleZh)}</p>`:''}${c.articleId?`<button class="quiet" data-context-id="${E(c.articleId)}" data-context-index="${i}">回到 ${E(c.title)} →</button>`:`<p class="small">来自 ${E(c.title||'词汇学习')}</p>`}`).join('')}<div class="rt-actions">${'speechSynthesis'in window?'<button class="ui-icon-button pill" id="rt-saved-speak" aria-label="浏览器朗读" title="浏览器朗读"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m11 5-6 4H2v6h3l6 4z"/><path d="M15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/></svg></button>':''}<button class="ui-icon-button quiet" id="rt-edit-meaning" aria-label="修改释义" title="修改释义"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m15 4 5 5M4 20l5-1L20 8a2 2 0 0 0-5-5L4 14z"/></svg></button><button class="ui-icon-button quiet" id="rt-remove-word" aria-label="移出词本" title="移出词本"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg></button></div>`);document.querySelectorAll('[data-context-id]').forEach(b=>b.onclick=()=>{$('#note').close();const origin=w.contexts[Number(b.dataset.contextIndex)];pendingReturn=origin||null;location.hash='read/'+b.dataset.contextId});if($('#rt-saved-speak'))$('#rt-saved-speak').onclick=()=>speak(w.word);$('#rt-edit-meaning').onclick=()=>{openCard('修改释义',`<label for="rt-edited-meaning" lang="en">${E(w.word)}</label><textarea id="rt-edited-meaning" maxlength="4000">${E(w.meaning)}</textarea><button class="primary" id="rt-meaning-save">保存</button>`);$('#rt-meaning-save').onclick=()=>{const meaning=$('#rt-edited-meaning').value.trim();if(!meaning){cardStatus('写下一点提示再保存',$('#rt-edited-meaning'));return}const current=db.words.find(x=>x.id===w.id);if(!current){notify('这条词语已被移出词本');$('#note').close();renderVocabulary($('#app'),ctx);return}current.meaning=meaning;current.updatedAt=new Date().toISOString();persist();savedWord(db.words.find(x=>x.id===w.id)||current)}};$('#rt-remove-word').onclick=()=>{removeRecord('words',w.id);persist();$('#note').close();renderVocabulary($('#app'),ctx);openCard('已移出词本','<button class="ui-icon-button pill" id="rt-undo-word" aria-label="撤销" title="撤销"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 4v6h6M4 10a8 8 0 1 1 0 7"/></svg></button>');$('#rt-undo-word').onclick=()=>{restoreRecord('words',w);persist();$('#note').close();renderVocabulary($('#app'),ctx)}}}
function review(container){const moveFocus=container.contains(document.activeElement);document.body.classList.add('is-reading');if(!reviewRound||reviewRound.index>=reviewRound.deck.length){R.saveRound('wordbook',null);reviewRound=null;container.innerHTML='<section class="test-page"><h1>这一轮，先到这里。</h1><p class="subtitle">这次回忆已记录；还不熟的词会稍后再出现。回忆成功不代表永久掌握。</p><button class="primary" id="rt-review-return">返回词本</button></section>';$('#rt-review-return').onclick=()=>renderVocabulary(container,ctx);focusReplacement(container.querySelector('h1'),moveFocus);return}
const expectedIndex=reviewRound.index,w=db.words.find(x=>x.id===reviewRound.deck[expectedIndex]);if(!w){R.skip('wordbook',reviewRound);review(container);return}reviewDeck=reviewRound.deck;reviewIndex=expectedIndex;const contexts=(w.contexts||[]).filter(c=>!vocabularyArticle||c.articleId===vocabularyArticle);container.innerHTML=`<section class="test-page rt-review"><div class="wl-study-top"><button class="ui-icon-button back reader-back" id="rt-review-exit" aria-label="退出回顾" title="退出回顾"><svg class="ui-glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m14 6-6 6 6 6M8 12h12"/></svg></button><span class="eyebrow">回顾 · ${expectedIndex+1} / ${reviewRound.deck.length}</span><button class="quiet" id="rt-review-skip">跳过</button></div><h1 lang="en">${E(w.word)}</h1><p class="small">先想一想它的意思，再查看释义。</p><button class="primary" id="rt-reveal" aria-expanded="${reviewRound.revealed}" aria-controls="rt-answer" ${reviewRound.revealed?'hidden':''}>查看释义</button><div id="rt-answer" role="region" aria-label="释义与用法" tabindex="-1" ${reviewRound.revealed?'':'hidden'}><p class="vocab-meaning rt-definition">${E(w.meaning)}</p>${contexts.map((c,i)=>`<p class="vocab-context" lang="en">${E(c.quote||'')}</p>${c.exampleZh?`<p class="small">${E(c.exampleZh)}</p>`:''}${c.articleId?`<button class="quiet" data-review-context="${i}">回到 ${E(c.title||'原文')} →</button>`:''}`).join('')}<div class="rt-actions"><button class="pill" data-review="again">还不熟</button><button class="primary" data-review="recalled">想起来了</button></div></div></section>`;
R.saveRound('wordbook',reviewRound);$('#rt-review-exit').onclick=()=>{reviewResume=false;renderVocabulary(container,ctx)};const valid=b=>b.isConnected&&reviewRound?.index===expectedIndex;
const skipButton=$('#rt-review-skip');skipButton.onclick=()=>{if(!valid(skipButton))return;R.skip('wordbook',reviewRound);review(container)};
const reveal=$('#rt-reveal');reveal.onclick=()=>{if(!valid(reveal)||reviewRound.revealed)return;const moveFocus=reveal.contains(document.activeElement);reviewRound.revealed=true;$('#rt-reveal').hidden=true;$('#rt-reveal').setAttribute('aria-expanded','true');$('#rt-answer').hidden=false;R.saveRound('wordbook',reviewRound);focusReplacement($('#rt-answer'),moveFocus)};
document.querySelectorAll('[data-review-context]').forEach(b=>b.onclick=()=>{if(!valid(b)||!reviewRound.revealed)return;const origin=contexts[Number(b.dataset.reviewContext)];pendingReturn=origin;reviewOrigin=origin;reviewResume=true;R.saveRound('wordbook',reviewRound);if(consent==='local')try{sessionStorage.setItem('naodai-review-origin-v1',JSON.stringify(origin))}catch{}location.hash='read/'+origin.articleId});
document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{if(!valid(b)||!reviewRound.revealed)return;const current=db.words.find(x=>x.id===w.id);if(!current){R.skip('wordbook',reviewRound);notify('这条词语已被移出词本');review(container);return}const response=b.dataset.review;if(!R.respond('wordbook',reviewRound,current,response))return;if(current){current.lastResponse=response;current.lastReviewedAt=new Date(R.get(w).lastPracticeAt).toISOString();current.updatedAt=current.lastReviewedAt;persist()}review(container)});focusReplacement(container.querySelector('h1'),moveFocus)}
function reviewContexts(item){const k=R.key(item);return db.words.filter(w=>R.key(w)===k).flatMap(w=>w.contexts||[]).filter(c=>c.articleId)}
function openReviewContext(origin,returnTarget='wordbook',scope='wordbook'){pendingReturn=origin;reviewOrigin={...origin,returnTarget,scope};reviewResume=returnTarget==='wordbook';if(consent==='local')try{sessionStorage.setItem('naodai-review-origin-v1',JSON.stringify(reviewOrigin))}catch{}location.hash='read/'+origin.articleId}
function reviewReturnControl(area,r){if(!reviewOrigin&&consent==='local')try{reviewOrigin=JSON.parse(sessionStorage.getItem('naodai-review-origin-v1'))}catch{}if(!reviewOrigin||reviewOrigin.articleId!==r.id||!(reviewOrigin.returnTarget==='vocabulary'?R.exportData().rounds[reviewOrigin.scope]?.round:R.loadRound('wordbook',db.words)))return;const origin={...reviewOrigin},ticket=generation;requestAnimationFrame(()=>{if(ticket!==generation||!area.isConnected)return;const para=area.querySelector('[data-paragraph="'+Number(origin.paragraphIndex)+'"]');para?.scrollIntoView?.({block:'center'});para?.classList.add('rt-return-context')});const b=document.createElement('button');b.id='rt-back-review';b.className='quiet';b.textContent='继续刚才的回顾 →';area.before(b);b.onclick=()=>{const target=reviewOrigin?.returnTarget||'wordbook';reviewResume=target==='wordbook';reviewOrigin=null;try{sessionStorage.removeItem('naodai-review-origin-v1')}catch{}location.hash=target};cleanups.push(()=>b.remove())}

function saveVocabularyAnnotation(value,callback){askStorage(()=>{let a=value.id?db.annotations.find(x=>x.id===value.id):null;if(value.id&&!a){notify('这条笔记已被删除，请重新打开');return}const now=new Date().toISOString();if(a){Object.assign(a,value,{updatedAt:now})}else{a={...value,id:uid(),kind:'vocabulary',articleId:null,createdAt:now,updatedAt:now};db.annotations.push(a)}persist();callback?.(a)})}
function removeAnnotation(id){const a=db.annotations.find(x=>x.id===id);if(!a)return null;const copy={...a};removeRecord('annotations',id);persist();repaint();return copy}
function restoreAnnotation(a){restoreRecord('annotations',a);persist();repaint()}
addEventListener('review-storage-error',()=>notify('回顾进度暂存在本次打开期间，请保留页面'));
window.ReaderTools={backupSnapshot:()=>JSON.parse(JSON.stringify(db)),replaceBackup:value=>{db=JSON.parse(JSON.stringify(value))},reviewContexts,openReviewContext,openAnnotationOrigin:id=>{const a=db.annotations.find(x=>x.id===id);if(a?.articleId){pendingReturn={articleId:a.articleId,paragraphIndex:a.paragraphIndex};location.hash='read/'+a.articleId}},getAnnotations:()=>db.annotations,saveVocabularyAnnotation,removeAnnotation,restoreAnnotation,editReadingNote:noteEditor,saveEntry,hasEntry,askStorage,storageChoice:()=>consent,speak,storageLabel,beforeExternalDialog,attach,cleanup,renderPassage,renderVocabulary,openVocabulary,afterFinish,exportData,exportFile,_test:{lookup,normalize,validAnnotations,decorate,showWord,showSentence,setMarkMode,captureSelection,noteEditor,addAnnotation,db:()=>db,consent:()=>consent}};
